<?php
declare(strict_types=1);use Vendi\Database\Connection;use Vendi\Http\ApiGuard;use Vendi\Risk\RiskService;
require dirname(__DIR__,3).'/vendor/autoload.php';session_start();header('Content-Type: application/json; charset=utf-8');
try{$u=ApiGuard::session();if(($u['role']??'')!=='owner')throw new RuntimeException('Solo propietario.',403);ApiGuard::csrf();$d=json_decode(file_get_contents('php://input'),true,512,JSON_THROW_ON_ERROR);$db=Connection::make(['host'=>getenv('DB_HOST')?:'127.0.0.1','port'=>(int)(getenv('DB_PORT')?:3306),'database'=>getenv('DB_DATABASE')?:'vendi','username'=>getenv('DB_USERNAME')?:'root','password'=>getenv('DB_PASSWORD')?:'']);(new RiskService($db))->review((int)$u['business_id'],(int)$d['id'],(int)$u['id'],(string)$d['status']);echo json_encode(['ok'=>true]);}catch(Throwable$e){http_response_code(in_array((int)$e->getCode(),[401,403],true)?(int)$e->getCode():422);echo json_encode(['ok'=>false,'error'=>$e->getMessage()],JSON_UNESCAPED_UNICODE);}